import{describe,it,expect}from"vitest";import{modernIndiaTimeline,governorsGeneralCatalog,britishActsCatalog,revoltsCatalog,reformsCatalog,nationalMovementsCatalog,historicCentersMapData,filterTimelineEvents,getEventById,filterGovernorsGeneral,filterBritishActs,filterRevolts,filterReforms,filterNationalMovements,getHistoricCenterById}from"../../frontend/making-of-modern-india/modern-india-timeline.js";const REQUIRED_TIMELINE_FIELDS=["id","year","date","title","category","era","location","description","historicalSignificance"];describe("Timeline Dataset Integrity (1757–1947)",()=>{it("contains at least 20 verified chronological events spanning from 1757 to 1947",()=>{expect(modernIndiaTimeline.length).toBeGreaterThanOrEqual(20),expect(modernIndiaTimeline[0].year).toBe(1757),expect(modernIndiaTimeline[modernIndiaTimeline.length-1].year).toBe(1947)}),it("every timeline event contains required properties with non-empty text",()=>{modernIndiaTimeline.forEach((e,t)=>{REQUIRED_TIMELINE_FIELDS.forEach(n=>{expect(e,`Timeline event at index ${t} missing field ${n}`).toHaveProperty(n),"string"==typeof e[n]?expect(e[n].trim().length).toBeGreaterThan(0):"number"==typeof e[n]&&expect(e[n]).toBeGreaterThan(1700)})})}),it("all timeline event IDs are unique",()=>{const e=modernIndiaTimeline.map(e=>e.id);expect(new Set(e).size).toBe(e.length)})}),describe("Timeline Filtering & Search Helpers",()=>{it("retrieves timeline event by ID",()=>{const e=getEventById("evt-1757-plassey");expect(e).toBeDefined(),expect(e.title).toContain("Battle of Plassey")}),it("filters timeline events by era correctly",()=>{const e=filterTimelineEvents("","EIC Expansion (1757–1857)");expect(e.length).toBeGreaterThan(0),expect(e.every(e=>"EIC Expansion (1757–1857)"===e.era)).toBe(!0)}),it("filters timeline events by category correctly",()=>{const e=filterTimelineEvents("","all","Revolt");expect(e.length).toBeGreaterThan(0),expect(e.every(e=>"Revolt"===e.category)).toBe(!0)}),it("filters timeline events by search query",()=>{const e=filterTimelineEvents("Bentinck");expect(e.length).toBeGreaterThan(0),expect(e[0].title).toContain("Sati");const t=filterTimelineEvents("Quit India");expect(t.length).toBeGreaterThan(0),expect(t[0].title).toContain("Quit India")}),it("returns empty array when search query matches nothing",()=>{const e=filterTimelineEvents("NonExistentModernIndiaEventXYZ");expect(e).toEqual([])})}),describe("Governors-General & Viceroys Catalogue",()=>{it("contains entries for major Governors-General and Viceroys",()=>{expect(governorsGeneralCatalog.length).toBeGreaterThanOrEqual(10);const e=governorsGeneralCatalog.map(e=>e.name);expect(e).toContain("Warren Hastings"),expect(e).toContain("Lord Cornwallis"),expect(e).toContain("Lord William Bentinck"),expect(e).toContain("Lord Dalhousie"),expect(e).toContain("Lord Canning")}),it("filters Governors-General by name or policy",()=>{const e=filterGovernorsGeneral("Dalhousie");expect(e.length).toBe(1),expect(e[0].name).toContain("Dalhousie")})}),describe("British Legislative Acts Catalogue",()=>{it("defines major legislative acts from 1773 to 1947",()=>{expect(britishActsCatalog.length).toBeGreaterThanOrEqual(8);const e=britishActsCatalog.map(e=>e.year);expect(e).toContain(1773),expect(e).toContain(1858),expect(e).toContain(1919),expect(e).toContain(1935),expect(e).toContain(1947)}),it("filters British Acts by search term",()=>{const e=filterBritishActs("1935");expect(e.length).toBe(1),expect(e[0].title).toContain("1935")})}),describe("Revolts, Reforms, & Freedom Movements Catalogs",()=>{it("contains historical revolts with leaders and regions",()=>{expect(revoltsCatalog.length).toBeGreaterThanOrEqual(5);const e=filterRevolts("Paika");expect(e.length).toBe(1),expect(e[0].leader).toContain("Bakshi")}),it("contains social reform legislation and reformers",()=>{expect(reformsCatalog.length).toBeGreaterThanOrEqual(4);const e=filterReforms("Sati");expect(e.length).toBe(1),expect(e[0].reformer).toContain("Raja Ram Mohan Roy")}),it("contains primary freedom movements and objectives",()=>{expect(nationalMovementsCatalog.length).toBeGreaterThanOrEqual(4);const e=filterNationalMovements("Non-Cooperation");expect(e.length).toBe(1),expect(e[0].name).toContain("Non-Cooperation")})}),describe("Interactive Historic Centers Map Data",()=>{it("defines map coordinates and historical details for key epicenters",()=>{expect(historicCentersMapData.length).toBeGreaterThanOrEqual(8);const e=getHistoricCenterById("center-plassey");expect(e).toBeDefined(),expect(e.name).toContain("Plassey"),expect(e.year).toBe("1757")})});